 let herbCount=Number(localStorage.getItem('emberHerbs')||0);
 let muted=false,audio=null;
 const rand=(x,y)=>{let n=Math.sin(x*127.1+y*311.7+6.17)*43758.5453;return n-Math.floor(n)};
-function resize(){const r=game.getBoundingClientRect();const aspect=r.width/r.height;viewW=Math.max(320,Math.round(480*Math.min(1,r.width/760)));viewH=Math.round(viewW/aspect);viewH=Math.min(360,Math.max(180,viewH));canvas.width=viewW;canvas.height=viewH;scale=viewW/480}
+function resize(){const r=game.getBoundingClientRect();const aspect=r.width/r.height;viewW=Math.max(320,Math.round(480*Math.min(1,r.width/760)));viewH=Math.max(180,Math.round(viewW/aspect));canvas.width=viewW;canvas.height=viewH;scale=viewW/480}
 new ResizeObserver(resize).observe(game);resize();
 function tile(x,y){return world[y]?.[x]??'water'}
 function setWorld(){for(let y=0;y<MH;y++){world[y]=[];for(let x=0;x<MW;x++){let edge=Math.min(x,y,MW-1-x,MH-1-y);let n=rand(x,y),g=Math.sin(x*.17)+Math.cos(y*.14)+Math.sin((x+y)*.09);let t=edge<3?'water':(g+n*1.3>1.3?'forest':g+n>-.25?'grass':'flowers');world[y][x]=t}}
 // Heartland meadow around the village

