function drawEnemy(e,cx,cy){let x=e.x-cx,y=e.y-cy+Math.sin(e.phase)*2;box(x-7,y+5,14,5,'#203d36aa');box(x-7,y-3,14,10,e.hit>0?'#fff2b0':'#72b77c');box(x-4,y-6,9,7,e.hit>0?'#fff2b0':'#90d391');box(x-3,y,2,2,'#293c30');box(x+2,y,2,2,'#293c30')}
function drawMap(){box(0,0,viewW,viewH,'#13282bdc');let size=Math.min(viewH*.7,viewW*.66),x=(viewW-size)/2,y=(viewH-size)/2;box(x-5,y-5,size+10,size+10,'#293d35');for(let yy=0;yy<MH;yy++)for(let xx=0;xx<MW;xx++){let t=tile(xx,yy),c=t==='water'?'#467f85':t==='forest'?'#456348':t==='path'?'#bea574':t==='stone'?'#999780':'#71925c';ctx.fillStyle=c;ctx.fillRect(x+xx/MW*size,y+yy/MH*size,size/MW+.5,size/MH+.5)}ctx.fillStyle='#ffdf86';ctx.fillRect(x+player.x/(MW*TILE)*size-2,y+player.y/(MH*TILE)*size-2,5,5);text('GREENWOLD FRONTIER',viewW/2,y-12,9,'#f8e8b7');text('M  ·  CLOSE MAP',viewW/2,y+size+17,8,'#e7d8ac')}
function render(){let cx=Math.max(0,Math.min(MW*TILE-viewW,player.x-viewW/2)),cy=Math.max(0,Math.min(MH*TILE-viewH,player.y-viewH/2));box(0,0,viewW,viewH,'#397b86');let sx=Math.floor(cx/TILE),sy=Math.floor(cy/TILE);for(let y=sy;y<=sy+Math.ceil(viewH/TILE)+1;y++)for(let x=sx;x<=sx+Math.ceil(viewW/TILE)+1;x++)drawTile(x*TILE-cx,y*TILE-cy,tile(x,y),x,y);for(const h of herbs)if(!h.taken){let x=h.x*TILE-cx,y=h.y*TILE-cy;box(x+7,y+8,2,6,'#398451');box(x+4,y+6,4,3,'#a6d77e');box(x+9,y+4,4,3,'#badf8c');box(x+7,y+3,2,2,'#f1e8a4')}let visible=decor.filter(d=>d.x*TILE-cx>-60&&d.x*TILE-cx<viewW+60&&d.y*TILE-cy>-50&&d.y*TILE-cy<viewH+50).sort((a,b)=>a.y-b.y);for(const d of visible)drawDecor(d,cx,cy);for(const e of enemies)if(e.alive&&e.x-cx>-20&&e.x-cx<viewW+20&&e.y-cy>-20&&e.y-cy<viewH+20)drawEnemy(e,cx,cy);actor(player.x-cx,player.y-cy,player.dir,walk,player.invuln>0&&Math.floor(performance.now()/90)%2?'#f7efe0':'#466e9d','#e9c574');if(attackFlash>0){let dx=player.dir==='left'?-12:player.dir==='right'?12:0,dy=player.dir==='up'?-10:player.dir==='down'?10:0;ctx.strokeStyle='#fff0a6';ctx.lineWidth=2;ctx.beginPath();ctx.arc(player.x-cx+dx,player.y-cy+dy,12,-.9,1.3);ctx.stroke()}if(mapOpen)drawMap();updateUI()}
function updateUI(){document.querySelector('#hearts').textContent='♥'.repeat(player.hp)+'♡'.repeat(player.maxHp-player.hp);document.querySelector('#level').textContent=player.level;document.querySelector('#gold').textContent=player.gold;let t=['Find Mira near the old stone well.','Gather 3 moon herbs in the eastern meadow.','Return to Mira with the moon herbs.','The village is safe. Explore the Greenwold!'];document.querySelector('#questText').textContent=t[Math.min(quest,3)];document.querySelector('#questTitle').textContent=['✧ A STRANGER’S REQUEST','✧ MOON HERB REMEDY','✧ BACK TO THE VILLAGE','✧ THE WORLD IS YOURS'][Math.min(quest,3)]}
function showToast(s){let el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}function panel(title,content,button='CONTINUE',action=null){dialogue=action;document.querySelector('#panelTitle').textContent=title;document.querySelector('#panelText').innerHTML=content;document.querySelector('#panelButton').textContent=button;document.querySelector('#panel').classList.add('open')}function closePanel(){document.querySelector('#panel').classList.remove('open');let fn=dialogue;dialogue=null;if(fn)fn()}document.querySelector('#panelButton').addEventListener('click',closePanel);function nearby(a,b,dist=23){return Math.hypot(a.x-b.x,a.y-b.y)<dist}

