function nearby(a,b,dist=23){return Math.hypot(a.x-b.x,a.y-b.y)<dist}
function interact(){if(document.querySelector('#panel').classList.contains('open'))return;let mira=decor.find(d=>d.type==='mira');if(nearby(player,{x:(mira.x+.5)*TILE,y:(mira.y+.5)*TILE},28)){if(quest===0){panel('MIRA OF GREENWOLD','“The slimes have soured our well. Could you find <b>three moon herbs</b> in the eastern meadow? They glow pale gold after the rain.”','I’LL HELP',()=>{quest=1;persist();showToast('Quest started: gather 3 moon herbs')});return}if(quest===1){panel('MIRA OF GREENWOLD',`“The moon herbs grow east of the village. You’ve found <b>${herbCount}/3</b> so far.”`,'GOT IT');return}if(quest===2){panel('MIRA OF GREENWOLD','“These are perfect! The water will be sweet again by morning. Please, take this for your trouble.”','THANK YOU',()=>{quest=3;player.gold+=25;player.xp+=30;levelCheck();persist();showToast('Quest complete! +25 gold · +30 XP')});return}panel('MIRA OF GREENWOLD','“The well is clear, thanks to you! There’s more to this world than our little village. Follow the old trail east to the ruins.”','GOODBYE');return}let dist=Infinity,chosen=null;for(const d of decor){if(d.type==='sign'||d.type==='well'){let q={x:(d.x+.5)*TILE,y:(d.y+.5)*TILE},dd=Math.hypot(player.x-q.x,player.y-q.y);if(dd<dist){dist=dd;chosen=d}}}if(chosen&&dist<30){if(chosen.type==='sign')panel('VILLAGE NOTICE','“Welcome to Greenwold. Moon herbs grow in the sunny meadow east of here. Beware the slimes beyond the lantern road.”','CLOSE');else panel('THE OLD WELL','A faint green shimmer ripples beneath the stones. Mira might know what’s wrong.','CLOSE');return}for(const h of herbs)if(!h.taken&&Math.hypot(player.x-(h.x+.5)*TILE,player.y-(h.y+.5)*TILE)<25){h.taken=true;herbCount++;player.xp+=5;levelCheck();persist();showToast(`Moon herb gathered · ${herbCount}/3`);if(quest===1&&herbCount>=3){quest=2;persist();showToast('You have enough herbs. Return to Mira!')}return}showToast('Nothing to gather nearby.')}
function levelCheck(){if(player.xp>=player.level*30){player.xp-=player.level*30;player.level++;player.maxHp=Math.min(5,player.maxHp+1);player.hp=player.maxHp;showToast(`Level up! You are now level ${player.level}`)}}function persist(){localStorage.setItem('emberQuest',quest);localStorage.setItem('emberHerbs',herbCount)}function playTone(freq,duration,type='sine'){if(muted)return;try{audio??=new AudioContext();let osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch{}}
function attack(){if(attackCd>0)return;attackCd=.38;attackFlash=.18;playTone(190,.08,'square');let hit=false;for(const e of enemies){if(!e.alive||Math.hypot(e.x-player.x,e.y-player.y)>30)continue;let dx=e.x-player.x,dy=e.y-player.y,face={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[player.dir];if(dx*face[0]+dy*face[1]<-4)continue;e.hp--;e.hit=.15;hit=true;if(e.hp<=0){e.alive=false;player.gold+=2+Math.floor(rand(e.homeX,e.homeY)*4);player.xp+=10;levelCheck();showToast('Slime defeated · +'+'gold')}else showToast('A solid hit!')}if(!hit&&enemies.some(e=>e.alive&&Math.hypot(e.x-player.x,e.y-player.y)<45))showToast('Face the slime and strike!')}

