if(!hit&&enemies.some(e=>e.alive&&Math.hypot(e.x-player.x,e.y-player.y)<45))showToast('Face the slime and strike!')}
function canWalk(px,py){let tx=Math.floor(px/TILE),ty=Math.floor(py/TILE);if(tx<0||ty<0||tx>=MW||ty>=MH)return false;let t=tile(tx,ty);if(t==='water'||t==='forest')return false;for(const d of decor){if(['house','houseBlue'].includes(d.type)&&px>d.x*TILE-3&&px<(d.x+d.w)*TILE+3&&py>d.y*TILE-2&&py<(d.y+d.h)*TILE-2)return false;if(['well','ruin','shrine'].includes(d.type)&&Math.abs(px-(d.x+.5)*TILE)<12&&Math.abs(py-(d.y+.5)*TILE)<12)return false}return true}let joy={x:0,y:0};function move(dt){let x=0,y=0;if(keys.has('ArrowLeft')||keys.has('a')||keys.has('A'))x--;if(keys.has('ArrowRight')||keys.has('d')||keys.has('D'))x++;if(keys.has('ArrowUp')||keys.has('w')||keys.has('W'))y--;if(keys.has('ArrowDown')||keys.has('s')||keys.has('S'))y++;x+=joy.x;y+=joy.y;let len=Math.hypot(x,y);if(len>1){x/=len;y/=len}if(len>.08){walk+=dt*8;if(Math.abs(x)>Math.abs(y))player.dir=x<0?'left':'right';else player.dir=y<0?'up':'down';let speed=68,nx=player.x+x*speed*dt,ny=player.y+y*speed*dt;if(canWalk(nx,player.y))player.x=nx;if(canWalk(player.x,ny))player.y=ny}else walk+=dt*1.6}
function bindStick(){let stick=document.querySelector('#stick'),nub=document.querySelector('#nub'),active=null;function update(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=r.width*.34,len=Math.hypot(dx,dy);if(len>max){dx*=max/len;dy*=max/len}joy.x=dx/max;joy.y=dy/max;nub.style.transform=`translate(${dx}px,${dy}px)`}stick.addEventListener('pointerdown',e=>{active=e.pointerId;stick.setPointerCapture(active);update(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===active)update(e)});function end(e){if(e.pointerId!==active)return;active=null;joy={x:0,y:0};nub.style.transform=''}stick.addEventListener('pointerup',end);stick.addEventListener('pointercancel',end)}bindStick();document.querySelector('#attack').addEventListener('pointerdown',e=>{e.preventDefault();attack()});document.querySelector('#interact').addEventListener('pointerdown',e=>{e.preventDefault();interact()});document.querySelector('#sound').onclick=()=>{muted=!muted;document.querySelector('#sound').textContent=muted?'♫̸':'♫';if(!muted)playTone(600,.08)};

